file_buffer(struct magic_set *ms, int fd, const char *inname __attribute__ ((__unused__)),
    const void *buf, size_t nb)
{
        int m = 0, rv = 0, looks_text = 0;
        const unsigned char *ubuf = CAST(const unsigned char *, buf);
        unichar *u8buf = NULL;
        size_t ulen;
        const char *code = NULL;
        const char *code_mime = "binary";
        const char *type = "application/octet-stream";
        const char *def = "data";
        const char *ftype = NULL;

        if (nb == 0) {
                def = "empty";
                type = "application/x-empty";
                goto simple;
        } else if (nb == 1) {
                def = "very short file (no magic)";
                goto simple;
        }

        if ((ms->flags & MAGIC_NO_CHECK_ENCODING) == 0) {
                looks_text = file_encoding(ms, ubuf, nb, &u8buf, &ulen,
                    &code, &code_mime, &ftype);
        }

#ifdef __EMX__
        if ((ms->flags & MAGIC_NO_CHECK_APPTYPE) == 0 && inname) {
                m = file_os2_apptype(ms, inname, buf, nb);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try os2_apptype %d]\n", m);
                switch (m) {
                case -1:
                        return -1;
                case 0:
                        break;
                default:
                        return 1;
                }
        }
#endif
#if HAVE_FORK
        /* try compression stuff */
        if ((ms->flags & MAGIC_NO_CHECK_COMPRESS) == 0) {
                m = file_zmagic(ms, fd, inname, ubuf, nb);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try zmagic %d]\n", m);
                if (m) {
                        goto done_encoding;
                }
        }
#endif
        /* Check if we have a tar file */
        if ((ms->flags & MAGIC_NO_CHECK_TAR) == 0) {
                m = file_is_tar(ms, ubuf, nb);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try tar %d]\n", m);
                if (m) {
                        if (checkdone(ms, &rv))
                                goto done;
                }
        }

        /* Check if we have a CDF file */
        if ((ms->flags & MAGIC_NO_CHECK_CDF) == 0) {
                m = file_trycdf(ms, fd, ubuf, nb);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try cdf %d]\n", m);
                if (m) {
                        if (checkdone(ms, &rv))
                                goto done;
                }
        }

        /* try soft magic tests */
        if ((ms->flags & MAGIC_NO_CHECK_SOFT) == 0) {
                m = file_softmagic(ms, ubuf, nb, NULL, NULL, BINTEST,
                    looks_text);
                if ((ms->flags & MAGIC_DEBUG) != 0)
                        (void)fprintf(stderr, "[try softmagic %d]\n", m);
                if (m) {
#ifdef BUILTIN_ELF
                        if ((ms->flags & MAGIC_NO_CHECK_ELF) == 0 && m == 1 &&
                            nb > 5 && fd != -1) {
                                /*
                                 * We matched something in the file, so this
                                 * *might* be an ELF file, and the file is at
                                 * least 5 bytes long, so if it's an ELF file
                                 * it has at least one byte past the ELF magic
                                 * number - try extracting information from the
                                 * ELF headers that cannot easily * be
                                 * extracted with rules in the magic file.
                                 */
                                m = file_tryelf(ms, fd, ubuf, nb);
                                if ((ms->flags & MAGIC_DEBUG) != 0)
                                        (void)fprintf(stderr, "[try elf %d]\n",
                                            m);
                        }
#endif
                        if (checkdone(ms, &rv))
                                goto done;
                }
        }
---
                        goto done;
                }

        } else {
                /* Windows refuses to read from a big console buffer. */
                size_t howmany =
#if defined(WIN32)
                                _isatty(fd) ? 8 * 1024 :
#endif
                                ms->bytes_max;
                if ((nbytes = read(fd, (char *)buf, howmany)) == -1) {
                        if (inname == NULL && fd != STDIN_FILENO)
                                file_error(ms, errno, "cannot read fd %d", fd);
                        else
                                file_error(ms, errno, "cannot read `%s'",
                                    inname == NULL ? "/dev/stdin" : inname);
                        goto done;
                }
        }

        (void)memset(buf + nbytes, 0, SLOP); /* NUL terminate */
        if (file_buffer(ms, fd, inname, buf, (size_t)nbytes) == -1)
                goto done;
        rv = 0;
done:
        free(buf);
        if (fd != -1) {
                if (pos != (off_t)-1)
                        (void)lseek(fd, pos, SEEK_SET);
                close_and_restore(ms, inname, fd, &sb);
        }
out:
        return rv == 0 ? file_getbuffer(ms) : NULL;
}


public const char *
magic_buffer(struct magic_set *ms, const void *buf, size_t nb)
{
        if (ms == NULL)
                return NULL;
        if (file_reset(ms) == -1)
                return NULL;
        /*
         * The main work is done here!
         * We have the file name and/or the data buffer to be identified.
         */
        if (file_buffer(ms, -1, NULL, buf, nb) == -1) {
                return NULL;
        }
        return file_getbuffer(ms);
}
#endif

public const char *
magic_error(struct magic_set *ms)
{
        if (ms == NULL)
                return "Magic database is not open";
        return (ms->event_flags & EVENT_HAD_ERR) ? ms->o.buf : NULL;
}

public int
magic_errno(struct magic_set *ms)
{
        if (ms == NULL)
                return EINVAL;
        return (ms->event_flags & EVENT_HAD_ERR) ? ms->error : 0;
}

